window.MONSTER_CHUNK_136 = [{"name":"Dun Pudding","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"ooze","init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":3,"ac_touch":3,"ac_flat_footed":3,"ac_mods":"-5 Dex, -2 size, +0 natural","hp":87,"hd":"10d8+50","hdvalue":10,"fort":8,"ref":-2,"will":7,"defensive_abilities":["split (piercing and slashing, 10 hp)"],"immunities":["ooze traits"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"slam +8 (2d6+4 plus 2d6 acid plus grab)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"2d6+4 plus 2d6 acid"},{"type":"corrosion"}],"strength":17,"dexterity":1,"constitution":21,"wisdom":1,"charisma":1,"baseatk":7,"cmb":12,"cmb_special":"+4 vs. grapple","cmd":17,"cmd_special":"can't be tripped","skills":[{"skill":"Climb","value":11}],"environments":["any warm land","any warm underground"],"organizations":["solitary"],"treasure":"none","description_visual":"The ground in this area seems to be alive. Suddenly, a mass of flowing gunk and muck, the same texture and color as the ground, rises from the area and moves in your direction.","group":"Pudding","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Acid","kind":"Ex","details":"A dun pudding secretes a digestive acid that dissolves organic material and metal quickly, but doesn't affect stone. Each time a creature suffers damage from a dun pudding's acid, its clothing and armor take the same amount of damage from the acid. A DC 20 Reflex save prevents damage to clothing and armor. A metal or wooden weapon that strikes a dun pudding takes 2d6 acid damage unless the weapon's wielder succeeds on a DC 20 Reflex save. If a dun pudding remains in contact with a wooden or metal object for 1 full round, it inflicts 20 points of acid damage (no save) to the object. The save DCs are Constitution-based."},{"type":"Corrosion","kind":"Ex","details":"An opponent that is being constricted by a dun pudding suffers a -4 penalty on Reflex saves made to resist acid damage applying to clothing and armor."}],"description":"A variety of the black pudding, the dun pudding is found only in warm, dry, arid regions. It is light tan or brown in color.\n\nDun puddings attack by grabbing and constricting their prey.","ecology":"","habitat_society":"","credit":"The Dun Pudding originally appeared in the First Edition module S4 Lost Caverns of Tsjocanth (© TSR/ Wizards of the Coast, 1982) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Ekimmu","cr":7,"xp":3200,"alignment":"CE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"lifesense","modifier":"60 ft."}],"auras":["unnatural aura (30 ft.)"],"ac":19,"ac_touch":19,"ac_flat_footed":15,"ac_mods":"+5 deflection, +1 dodge, +3 Dex","hp":84,"hd":"8d8+40 (+8)","hdvalue":8,"fort":7,"ref":5,"will":10,"defensive_abilities":["channel resistance +4","incorporeal","rejuvenation"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"incorporeal touch +9 (7d6, DC 19 Fort half)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"malevolence"},{"type":"paralyzing howl"}],"dexterity":16,"intelligence":14,"wisdom":14,"charisma":21,"baseatk":6,"cmb":9,"cmd":28,"feats":[{"feat":"Ability Focus (malevolence)","type":"bonus"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":22},{"skill":"Intimidate","value":16},{"skill":"Knowledge (local)","value":10},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":14}],"languages":["Common"],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This spectral figure moves forward, its face bent and twisted in anguish.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Incorporeal Touch","kind":"Su","details":"By passing part of its incorporeal body through a foe's body as a standard action, the ekimmu inflicts 7d6 damage. This damage isn't negative energy-it manifests in the form of physical wounds and aches from supernatural aging. Creatures immune to magical aging are immune to this damage, but otherwise the damage bypasses all forms of damage reduction. A Fortitude save halves the damage inflicted."},{"type":"Lifesense","kind":"Su","details":"An ekimmu notices and locates living creatures within 60 ft., just as if it possessed the blindsight ability."},{"type":"Malevolence","kind":"Su","details":"The ekimmu's jealousy of the living is particularly potent. Once per round, the ekimmu can merge its body with a creature on the Material Plane. This ability is similar to a magic jar spell (CL 8th), except that it doesn't require a receptacle. To use this ability, the ekimmu must be adjacent to the target. The target can resist the attack with a successful DC 21 Will save. A creature that successfully saves is immune to that same ekimmu's malevolence for one day. The save DC is Charisma-based and includes a +2 bonus from the ekimmu's Ability Focus feat."},{"type":"Paralyzing Howl","kind":"Su","details":"At will, an ekimmu can let out a fearsome howl that paralyzes all within a 30 ft. radius for 1d4+1 rounds unless they succeed on a DC 19 Will save. A creature that successfully saves is immune to that ekimmu's howl for one day. The save DC is Charisma-based."},{"type":"Rejuvenation","kind":"Su","details":"In most cases, it's difficult to destroy an ekimmu through simple combat: the \"destroyed\" spirit restores itself in 2d6 days. Even the most powerful spells are usually only temporary solutions. The only way to permanently destroy an ekimmu is to determine the reason for its existence and set right whatever prevents it from entering the underworld."},{"type":"Unnatural Aura","kind":"Su","details":"Animals don't willingly approach within 30 ft. of an ekimmu, unless a master makes a DC 25 Handle Animal, Ride, or wild empathy check."}],"description":"An ekimmu is the evil ghost of one who has been denied entrance to the underworld and is doomed to wander the earth. It is greatly feared, for it attaches itself quite easily to virtually any living person regardless of whether that person has been acquainted with the dead one. Once it has possessed a living host, it is very difficult to exorcise.\n\nAn ekimmu roams the lands near where it was killed. Though it isn't bound to the area, it feels a sense of connection to it and rarely wanders more than a few miles from it. An ekimmu has no permanent lair and wanders its realm perpetually, always on the move.\n\nAn ekimmu roams the earth, seeking victims to possess and using its hosts to bring misfortune and death to the living. Its howling in the night is often the only warning of its approach. In battle, it uses its array of abilities to defeat and destroy its opponents, opening combat with its paralyzing howl and then using its malevolence to attack a target it deems weak-willed and open for possession.","ecology":"","habitat_society":""},{"name":"Flagstone Golem","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"construct","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":10,"ac_flat_footed":19,"ac_mods":"+1 Dex, +10 natural, -1 size","hp":74,"hd":"8d10+30","hdvalue":8,"fort":2,"ref":3,"will":2,"defensive_abilities":["energy absorption","flatten"],"dr":"10/ adamantine","immunities":["construct traits","magic"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +13 (2d8+6 plus stun)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"stunning blow"}],"strength":22,"dexterity":12,"wisdom":11,"charisma":1,"baseatk":8,"cmb":15,"cmd":26,"sq":[{"type":"camouflage"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"What you thought was a section of ordinary stone floor unfurls itself before your eyes, assuming a humanoid form about 10 ft. tall. The words \"You shall not pass\" echo throughout the area as the creature advances.","group":"Golem","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Camouflage","kind":"Ex","details":"While flattened, a flagstone golem is nearly indistinguishable from the surrounding floor. It takes a DC 25 Perception check to notice a flattened flagstone golem for what it is. Dwarves get a +2 bonus on Perception checks to notice a flattened flagstone golem."},{"type":"Energy Absorption","kind":"Su","details":"Any energy-based (acid, fire, cold, electricity, sonic) attack that directly targets a flagstone golem is absorbed into its body dealing no damage to the golem. A flagstone golem can use the absorbed energy to repair itself, healing 1 hit point for every 3 points of damage the attack would have otherwise dealt. Or it can release the energy in a 30-foot cone that deals 3d8 points of energy damage (of whatever type was absorbed) to all within the area. An affected opponent can attempt a DC 14 Reflex save to reduce the damage by half. The save DC is Constitutionbased. The flagstone golem can store the energy before releasing it as an energy blast for a number of rounds equal to half its Hit Dice (four rounds for the standard flagstone golem)."},{"type":"Flatten","kind":"Ex","details":"As a standard action, once per round, a flagstone golem can flatten its form to become (or appear to become) a section of floor, road, or any other stone surface. While flattened it cannot move or attack and its damage reduction increases to 20/adamantine. A flagstone golem can reform into its humanoid shape as a standard action."},{"type":"Immunity to Magic","kind":"Ex","details":"A flagstone golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted below. A transmute rock to mud spell slows it (as the slow spell) for 2d6 rounds, with no saving throw. A transmute mud to rock spell heals all its lost hit points. A stone to flesh spell doesn't actually change the golem's structure, but it negates the flagstone golem's damage reduction for 1 round."},{"type":"Stunning Blow","kind":"Ex","details":"Any creature hit by a flagstone golem's slam attack must succeed on a DC 16 Fortitude save or be stunned for 1 round. The save DC is Constitution-based and includes a +2 racial bonus."}],"description":"A flagstone golem is composed of large flat stones and bricks jointed and fitted together so as to allow the creature to fold itself flat. It is created to serve as guardians or servants by powerful spellcasters and has been the death of many an unsuspecting rogue. A flagstone golem stands 10 ft. tall and weighs 1,200 pounds. Its humanoid form is composed of flattened stones and bricks. Two darkened sockets on its head function as eyes. Its arms are thick and powerful and end in stony clenched fists. Though a flagstone golem cannot speak, when constructed, its creator can program up to 4 simple words or phrases (no more than 4 words in length) into it that are released when certain conditions are met. These conditions are programmed into the golem when it is constructed. Conditions can be as general or specific as necessary, but must be fairly simple, such as \"if anyone enters this room\" or \"if anyone touches this chest\". A flagstone golem tasked with guarding or securing a location usually flattens itself so as to go unnoticed to would-be-trespassers. When an interloper treads upon the golem, it unfurls itself into its humanoid form and attacks, crushing and pounding its unsuspecting victim with powerful blows from its fists. Construction A flagstone golem is constructed from brick, stone, various powders, and exotic liquids totaling 2,500 gp. FLAGSTONE GOLEM CL 11th; Price 30,000 gp Requirements Craft Construct, bull's strength, geas/ quest, magic mouth, polymorph any object, protection from energy, creator must be caster level 11th; Skill Craft (sculptures) or Craft (stonemasonry) DC 16; Cost 17,500.","ecology":"","habitat_society":""},{"name":"Giant Cobalt Viper","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"magical beast","subtypes":["extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"auras":["poison (20 ft., DC 17)"],"ac":22,"ac_touch":12,"ac_flat_footed":19,"ac_mods":"+3 Dex, +10 natural, -1 size","hp":104,"hd":"11d10+44","hdvalue":11,"fort":11,"ref":10,"will":6,"speed":[{"type":"land","speed":30},{"type":"climb","speed":20},{"type":"swim","speed":20}],"melee":"bite +17 (2d6+9 plus poison)","space":"10 ft.","reach":"5 ft.","strength":22,"dexterity":17,"constitution":18,"intelligence":2,"wisdom":17,"charisma":12,"baseatk":11,"cmb":18,"cmd":31,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Acrobatics","value":16},{"skill":"Climb","value":19},{"skill":"Perception","value":14},{"skill":"Stealth","value":12},{"skill":"Swim","value":14}],"environments":["any (Plane of Molten Skies)"],"organizations":["solitary","pair","nest (3-6)"],"treasure":"incidental","description_visual":"This creature appears to be a metallic blue-scaled snake with crystal eyes. Its forked red tongue flicks from its fanged mouth.","group":"Giant","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save DC 21 Fort; frequency 1/ round for 6 rounds; effect 1d6 Con damage; cure 2 consecutive saves. The save DC is Constitution-based and includes a +2 racial bonus."},{"type":"Poison Aura","kind":"Ex","details":"A cobalt viper's poison is so potent, that it exudes it in an aura around its body. A creature that starts its turn within the area is subjected to the cobalt viper's poison. The poison from this aura is weaker than its bite however, and deals only 1d2 points of Con damage (instead of 1d6 Con damage)."}],"description":"Cobalt vipers are poisonous snakes found on the Plane of Molten Skies. Whatever magic transported the Steel Garden to that realm is thought to have brought the vipers here as well. They are indigenous to the Garden and are virtually unknown outside of it.\n\nA cobalt viper appears to be constructed of metal; in fact its scales are actually a composite of the steel found within the Steel Garden and normal snake scales. How exactly these creatures came to exist is unknown. A typical cobalt viper is about 5 ft. long though species up to 12 ft. long or more have been sighted. Cobalt vipers are sometimes hunted by intelligent races for their scales. The scales are taken and fashioned into various pieces of jewelry or used to adorn armor and weapons.\n\nCobalt vipers are highly aggressive predators that prefer to attack from ambush. Normally, a cobalt viper trails its prey allowing its poison aura to sap the target's strength. After its prey is sufficiently weakened, the cobalt viper lunges from its hiding place and strikes.","ecology":"","habitat_society":""},{"name":"Giant Rhinoceros Beetle","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"vermin","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":9,"ac_flat_footed":20,"ac_mods":"+11 natural, -1 size","hp":85,"hd":"10d8+40","hdvalue":10,"fort":11,"ref":3,"will":3,"speed":[{"type":"land","speed":20}],"melee":"gore +12 (2d6+6), bite +12 (2d6+6)","space":"10 ft.","reach":"5 ft. (10 ft. with horn)","special_attacks":[{"type":"trample","details":"DC 21, 1d8+9"}],"strength":23,"dexterity":10,"constitution":18,"wisdom":10,"charisma":9,"baseatk":7,"cmb":14,"cmd":24,"cmd_special":"+8 vs. trip","environments":["warm forests"],"organizations":["cluster (2-5)","swarm (6-11)"],"treasure":"none","description_visual":"This creature appears as a giant beetle with a grayish-brown carapace and wing-covers and a large brownish-black  \"horn\" between its mandibles.","group":"Beetle","source":"Tome of Horrors Complete (3pp)","description":"These creatures are found in the warm jungles and forests of the world and spend their days searching for plants, fruits, and berries on which to sustain themselves. An adult rhinoceros beetle is about 12 ft. long.\n\nGiant rhinoceros beetles charge opponents, biting with their razor sharp mandibles and slashing with their horn.","ecology":"","habitat_society":"","credit":"The Rhinoceros Beetle originally appeared in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission."},{"name":"Gorgosaurus","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"animal","init":5,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+1 Dex, +10 natural, -2 size","hp":105,"hd":"14d8+42","hdvalue":14,"fort":12,"ref":10,"will":7,"speed":[{"type":"land","speed":40}],"melee":"bite +15 (3d6+14/19-20 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"swallow whole","details":"2d6+7, AC 15, 10 hp"}],"strength":25,"dexterity":13,"constitution":16,"intelligence":2,"wisdom":12,"charisma":10,"baseatk":10,"cmb":19,"cmb_special":"+4 vs. grapple","cmd":30,"feats":[{"feat":"Critical Focus"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":30}],"sq":[{"type":"powerful bite"}],"environments":["any shores","warm plains"],"organizations":["solitary","pack (2-4)"],"treasure":"none","description_visual":"This huge reptile has small two-fingered forelimbs, strong powerful legs, and an enormous mouth filled with rows of sharp teeth.","group":"Dinosaur","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Powerful Bite","kind":"Ex","details":"A gorgosaurus applies twice its Strength modifier to bite damage."}],"description":"A gorgosaurus is about 28 ft. long from snout to tail and weighs almost 6,000 pounds. Its coloration can vary from dark shades of green to various shades of gray. Its diet consists of anything it can catch and kill, including large animals such as mastodons and mammoths, brontosauruses, and other such creatures.\n\nA gorgosaurus's tactics are simple: charge, bite, swallow.","ecology":"","habitat_society":""},{"name":"Greater Acid Quasi-elemental","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"outsider","subtypes":["acid","elemental","extraplanar"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["fumes (5 ft., Fort DC 19)"],"ac":21,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+5 Dex, +8 natural, -2 size","hp":95,"hd":"10d10+40","hdvalue":10,"fort":7,"ref":12,"will":9,"dr":"10/-","immunities":["acid","elemental traits"],"weaknesses":["vulnerability to water"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":80}],"melee":"2 slams +14 (1d8+6 plus 1d8 acid)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"acid"},{"type":"drench"}],"strength":23,"dexterity":20,"constitution":19,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":10,"cmb":18,"cmd":33,"feats":[{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Knowledge (planes)","value":11},{"skill":"Perception","value":13},{"skill":"Stealth","value":10},{"skill":"Swim","value":27}],"languages":["Aquan"],"environments":["any (Quasi-Plane of Acid)"],"organizations":["solitary"],"treasure":"none","description_visual":"What was once a still puddle of green liquid rises up like a wave, lashing out with acid-dripping tendrils. In the midst of the pool, one can barely make out regions of darker green that form a vaguely human face.","group":"Quasi-elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Acid","kind":"Ex","details":"Acid quasi-elementals are living creatures of acid; any melee hit deals acid damage. Creatures hitting an acid quasi-elemental unarmed or with natural attacks take acid damage as though hit by the quasi-elemental's slam attack."},{"type":"Acid Swimmer","kind":"Ex","details":"Acid quasi-elementals cannot swim in water. The swim speed given in the statistics block is their movement only through acid pools or the acidic nature of their environment on their home plane."},{"type":"Drench","kind":"Ex","details":"The quasi-elemental's touch puts out torches, campfires, exposed lanterns, and other open flames of nonmagical origin if these are of Large size or smaller. The creature can dispel magical fire as dispel magic (caster level equals the quasi-elemental's HD)."},{"type":"Fumes","kind":"Ex","details":"The fumes from an acid quasi-elemental's body act as an inhaled poison. Creatures within 5 ft. of an acid quasi-elemental must make succeed on a Fortitude save or take 1 point of Constitution damage each round. This poison doesn't have a frequency; a creature is safe as soon as it moves more than 5 ft. away from the acid quasi-elemental."},{"type":"Vulnerability to Water","kind":"Ex","details":"An acid elemental erupts in a violent chemical reaction when touched by water. An acid quasi-elemental takes 1d4 points of fire damage for each gallon of water poured into it. The reaction is so violent that all creatures within 5 ft. of the acid quasi-elemental when the water hits it must succeed on a DC 15 Reflex save or take the same damage. Pouring water onto an acid quasi-elemental requires a successful ranged touch attack. Water from other sources, such as spells or effects that create water but don't specify an amount in gallons, deal 1d4 points of fire damage per caster level to an acid quasi-elemental within its area of effect. Damage from water-based attacks, like the slam attack of a water elemental, is increased by 50% against an acid quasi-elemental. Note that this reaction doesn't occur when the acid quasi-elemental touches water, only when water touches the acid quasi-elemental."}],"description":"Nestled among the various elemental there lies a plane composed entirely of acid. It is a place of noxious fumes and roiling, bubbling, pools. Plane jumpers do well to avoid this place as it is considered by many to be one of the deadliest, if not the deadliest, of the elemental-based planes. Acid quasi-elementals rarely journey from their native plane, except when summoned. They don't like the Material Plane and when called to the place, are usually angered and always a bit uncomfortable. They have no trouble moving on land, but prefer the sanctity of their native plane to all others. At rest, an acid quasi-elemental is a clear puddle of liquid with a slightly green hue. It can rise up like a wave in a manner similar to a water elemental, or ooze along solid surfaces by sending out tendrils and pulling itself along. Wherever it travels, it leaves behind a shallow trough that emits wisps of smoke. Acid quasi-elementals are almost always encountered in large pools of acid when on the Material Plane and rarely leave these pools when combating foes. A favored tactic is to grab a foe and pull it into the quasi-elemental's acid pool, subjecting it to massive amounts of acid damage.","ecology":"","habitat_society":""},{"name":"Greater Basilisk","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"magical beast","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":8,"ac_flat_footed":18,"ac_mods":"-1 Dex, +10 natural, -1 size","hp":85,"hd":"9d10+36","hdvalue":9,"fort":12,"ref":5,"will":4,"speed":[{"type":"land","speed":20}],"melee":"bite +14 (1d8+6) and 2 claws +14 (1d6+6 plus poison)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"foul breath"},{"type":"gaze"}],"strength":23,"dexterity":8,"constitution":18,"intelligence":2,"wisdom":12,"charisma":10,"baseatk":9,"cmb":16,"cmd":25,"cmd_special":"+12 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Great Fortitude"},{"feat":"Power Attack"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":12},{"skill":"Stealth","value":6}],"environments":["warm deserts"],"organizations":["solitary","pair"],"treasure":"standard","description_visual":"This creature looks like a thick-bodied reptile with eight legs. Its eyes glow with an eerie, pale green incandescence.","group":"Basilisk","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Foul Breath","kind":"Ex","details":"A greater basilisk's breath is extremely foul. Any creature in a space directly in front of a greater basilisk must succeed on a DC 18 Fortitude save or take 1d4 points of Constitution damage each round they remain in the area. A creature that successfully saves cannot be affected by the breath of the same greater basilisk for 24 hours. The save DC is Constitution-based."},{"type":"Gaze","kind":"Ex","details":"Turn to stone permanently (as stone to flesh), range 30 ft., Fortitude DC 18 negates. A creature petrified in this manner that is then coated (not just splashed) with fresh basilisk blood (taken from a basilisk no more that 1 hour dead) is instantly restored to flesh. A single greater basilisk contains enough blood to coat 1d4 Medium creatures in this manner. The save DC is Constitution-based."},{"type":"Poison","kind":"Ex","details":"Claw-injury; save Fort DC 18; frequency 1/ round for 6 rounds; effect 1d3 Con; cure 1 save."}],"description":"A larger and meaner cousin of the normal basilisk, the greater basilisk is a 12-foot long reptilian monster with dull brown skin and a yellow underbelly. Sages believe the greater basilisk hails from the Elemental Plane of Earth.\n\nGreater basilisks rear up on their hind legs and slash opponents with their poisonous claws while also using their deadly gaze attack. The breath of a greater basilisk is so foul that all creatures within 5 ft. can be affected by it just by entering or remaining in the area.","ecology":"","habitat_society":"","credit":"The Greater Basilisk originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Greater Obsidian Quasi-elemental","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"outsider","subtypes":["earth","elemental","extraplanar"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":7,"ac_flat_footed":19,"ac_mods":"-1 Dex, +12 natural, -2 size","hp":95,"hd":"10d10+40","hdvalue":10,"fort":7,"ref":6,"will":7,"dr":"10/-","immunities":["elemental traits"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":20}],"melee":"2 claws +17 (2d6+9/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death throes"},{"type":"molten glass","details":"2d8 fire, DC 19"}],"strength":28,"dexterity":8,"constitution":19,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":10,"cmb":21,"cmd":30,"feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Natural Attack","type":"bonus"},{"feat":"Power Attack"}],"skills":[{"skill":"Knowledge (planes)","value":11},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":4}],"languages":["Terran"],"environments":["any (Quasi-Plane of Obsidian)"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature is a powerfully built, roughly humanoid-shaped monolith of black stone. Its hands end in wicked, serrated and jagged claws. No facial features can be discerned.","group":"Quasi-elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Death Throes","kind":"Ex","details":"When reduced to 0 or less hit points, an obsidian quasi-elemental explodes in a cloud of razor-sharp bits of obsidian. A creature caught in the area can make a Reflex save for half damage. The save DC is Constitution-based."},{"type":"Molten Glass","kind":"Ex","details":"A successful hit against an obsidian quasi-elemental with a piercing or slashing weapon (or piercing or slashing natural attack) that deals damage equal to its current HD opens a wound that spurts molten glass. The wound bleeds for 1d4 rounds and any creature within 5 ft. must make a Reflex save or take fire damage from the splash. A new save must be made each round the wound bleeds and a creature is within the area. The save DC is Constitution-based."}],"description":"In a quasi-realm where elemental water and elemental fire conjoin, there exists a pocket plane known as the Quasi-plane of Obsidian; a plane of barren wastes and blackened rock, of razor-sharp obelisks and fields of sharpened glass. Creatures native to this plane appear as blackened obsidian with jagged, serrated, or clear-cut angles and edges. Some have barbed spikes adorning their elemental forms. Obsidian quasi-elementals are usually encountered on their home plane or on the Plane of Fire. Still some can be found on the Obsidian Plain in the Plane of Molten Skies (see the City of Brass by Necromancer Games). Most, however, prefer the serenity that the Quasi-plane of Obsidian offers, and thus they rarely venture forth unless summoned. Obsidian quasi-elementals are deadly combatants and strike with their sharpened claws, ripping and tearing at their opponents. They are relentless in their attacks and never give quarter.","ecology":"","habitat_society":""},{"name":"Hangman Tree","cr":7,"xp":3200,"alignment":"NE","size":"Huge","type":"plant","init":3,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["hallucinatory spores (50 ft. radius, DC 19, passive 2d6 minutes)"],"ac":20,"ac_touch":7,"ac_flat_footed":20,"ac_mods":"-1 Dex, +13 natural, -2 size","hp":76,"hd":"8d8+40","hdvalue":8,"fort":11,"ref":1,"will":5,"immunities":["plant traits"],"sr":19,"weaknesses":["paralyzed by cold","slowed by darkness","vulnerability to electricity"],"speed":[{"type":"land","speed":10}],"melee":"4 vines +13 (1d6+8 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"constrict","details":"1d6+8"},{"type":"swallow whole","details":"2d6+8 bludgeoning damage, AC 16, hp 7"}],"strength":27,"dexterity":8,"constitution":20,"intelligence":6,"wisdom":12,"charisma":10,"baseatk":6,"cmb":16,"cmb_special":"+4 vs. grapple","cmd":25,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Step Up"},{"feat":"Weapon Focus (vines)"}],"skills":[{"skill":"Perception","value":6},{"skill":"Stealth","value":0,"special":"+16 to hide in forests"}],"languages":["Common"],"environments":["temperate forests","warm forests"],"organizations":["solitary","pair"],"treasure":"half standard","description_visual":"A giant oak tree with few leaves and branches stands nearby.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Constrict","kind":"Ex","details":"Because it seizes its victims by the neck, a creature in the hangman tree's grasp cannot speak or cast spells with verbal components."},{"type":"Hallucinatory Spores","kind":"Ex","details":"As a standard action, a hangman tree can release a cloud of spores in a 50-foot radius spread. Creatures in the area must succeed on a DC 19 Will save or be affected as if by a charm monster spell for 2d6 minutes. Affected creatures believe the tree to be of some ordinary sort (or to be a treant or other such friendly tree creature). An affected creature becomes passive and refuses to attack the hangman tree during this time. This is a mind-affecting compulsion effect. The save DC is Constitution-based. An affected creature can attempt a new Will save (DC 19, +1 per previous save) each round. A creature that makes its save cannot be affected by the hallucinatory spores of that hangman's tree for 24 hours."},{"type":"Paralyzed by Cold","kind":"Ex","details":"Cold-based effects paralyze a hangman tree as if by a hold person spell."},{"type":"Slowed by Darkness","kind":"Ex","details":"Spells that generate darkness (such as darkness or deeper darkness) slow the hangman's tree (as the slow spell) for 1 round per caster level."},{"type":"Vines","kind":"Ex","details":"The vines of a hangman tree have 10 hit points and can be attacked by making a successful sunder attempt. Attacking a hangman tree's vine doesn't provoke an attack of opportunity. If the vine is currently grappling a target, the hangman tree takes a -4 penalty on its opposed attack roll to resist the sunder attempt. Severing a vine deals no damage to a hangman tree."}],"description":"Close inspection reveals a scar-like marking on the lower part of the trunk of this tree; this is where undigested creatures or gear is expelled after digestion. Hidden among the hangman tree's branches and leaves are its rope-like appendages that it uses to trap its prey. The hangman tree attacks by dropping its noose-like appendages around prey and yanking victims upwards. Trapped prey is held until it dies or is dropped into the hangman's trunk where it is digested.","ecology":"","habitat_society":"","credit":"The Hangman Tree originally appeared in EX1 Dungeonland (© TSR/ Wizards of the Coast, 1983) and is used by permission."},{"name":"Heat Swarm","cr":7,"xp":3200,"alignment":"NE","size":"Diminutive","type":"outsider","subtypes":["elemental","extraplanar","fire","swarm"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["fiery aura (20 ft., DC 16 Fort, 1d6 fire)"],"ac":21,"ac_touch":21,"ac_flat_footed":14,"ac_mods":"+6 Dex, +1 dodge, +4 size, +0 natural","hp":67,"hd":"9d10+18","hdvalue":9,"fort":7,"ref":12,"will":6,"dr":"10/-","immunities":["fire","weapon damage","construct traits","elemental traits","swarm traits"],"weaknesses":["swarm traits","vulnerability to cold"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"swarm (2d6 plus 2d6 fire and burn)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"burn","details":"2d6, DC 16"},{"type":"distraction","details":"DC 16"}],"strength":1,"dexterity":24,"constitution":14,"intelligence":6,"wisdom":10,"charisma":6,"baseatk":9,"feats":[{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":12},{"skill":"Knowledge (planes)","value":10},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":18},{"skill":"Survival","value":12}],"environments":["any (Para-Elemental Plane of Heat)"],"organizations":["solitary","mass (2-4 swarms)","holocaust (7-12 swarms)"],"treasure":"none","description_visual":"A hellish-red swirling mass of dancing flames advances toward you.","group":"Heat","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Fiery Aura","kind":"Ex","details":"Anyone within 20 ft. of a heat swarm must succeed on a DC 16 Fortitude save or take 1d6 points of heat damage per round from the intense heat. The save DC is Constitution-based."}],"description":"A heat swarm is a mass of flying, aggressive, foul-tempered elementals from the Para-Plane of Heat. A single heat elemental that makes up a heat swarm resembles a thumb-sized ball of fire with vaguely discernable facial features.\n\nHeat swarms are highly territorial and attack any creatures (other than their own kind) entering their domain. Several swarms often work together to drive away a common foe.\n\nWhen encountered on the Material Plane (which is a very rare occurrence indeed), a heat swarm is most often found in a highly unbearable (by human standards) climate such as an active volcano.\n\nA heat swarm attacks by moving on top of and engulfing its foe.","ecology":"","habitat_society":""},{"name":"Huge Gravity Elemental","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"outsider","subtypes":["elemental","extraplanar","gravity"],"init":12,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":19,"ac_flat_footed":10,"ac_mods":"+2 deflection, +8 Dex, +1 dodge, -2 size, +0 natural","hp":105,"hd":"10d10+50","hdvalue":10,"fort":8,"ref":15,"will":7,"defensive_abilities":["distortion"],"dr":"5/-","immunities":["elemental traits","missile weapons","mass-dependent spells"],"speed":[{"type":"fly","speed":100,"maneuverability":"perfect"}],"melee":"2 slams +16 (1d8+5)","ranged":"missile +16 (damage by type)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"engulf"},{"type":"gravity field","details":"crush 5/day, 30 ft. radius, DC 20, 4d6 bludgeoning"}],"strength":20,"dexterity":27,"constitution":20,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":10,"cmb":17,"cmd":38,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Throw Anything","type":"bonus"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":25},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":13}],"languages":["Gravity Manipulation"],"sq":[{"type":"perfect flier"}],"environments":["any (Plane of Gravity)"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature resembles a miniature black hole hovering several ft. off the ground. It is a circular region of absolute blackness, with a bizarre distortion around its edges as it warps light waves. Four spiraling, rotating arms of debris and light surround the circular region of darkness. Its facial features are small points of light, almost like stars.","group":"Elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Distortion","kind":"Su","details":"The manipulation of light waves around a gravity elemental grants it a +2 deflection bonus to its Armor Class."},{"type":"Engulf","kind":"Ex","details":"A gravity elemental that starts its turn grappling a creature or holding and object up to one size smaller than itself can absorb the creature or object into its swirling form as a full-round action. An engulfed creature or object takes damage equal to the elemental's slam attack each round it remains engulfed and can take no action other than trying to break free by rolling its CMB vs. the gravity elementals CMD. The gravity elemental gains the grappled condition as long as it has a creature engulfed, and it can only engulf one creature at a time. A creature that dies while engulfed by a gravity elemental is smashed into atoms and can only be restored to life by a miracle, wish, or the intervention of a deity. An object that is destroyed while it is engulfed by a gravity elemental is destroyed forever and cannot be restored. There is a 1% non-cumulative chance each round that an engulfed creature or object is sent to a random plane."},{"type":"Gravity Field","kind":"Su","details":"A gravity elemental's manipulation of gravity function like the reverse gravity and telekinesis spells (CL equal to HD). The maximum weight an Elder gravity elemental can lift with its telekinesis isn't restricted to 375 lbs. The effects of the gravity field are centered on the gravity elemental and move with it. Additionally, by increasing the pull of gravity around itself a gravity elemental can make creatures within a certain radius too heavy to move, or crush them to a pulp. Hold: As a full-round action a gravity elemental can cause all corporeal creatures in its area of effect to become too heavy to move. Creatures in the gravity elemental's gravity field must succeed on a Fortitude save or gain the held condition until the gravity elemental releases them or they break free. A flying creature has a -4 penalty applied to the save; failure means it is unable to remain airborne and must land. The check DC is Strength-based. The gravity elemental can maintain this ability each round as a fullround action. The area of effect and save DC depend on the size of the elemental. If the gravity elemental maintains this ability, on successive rounds a held creature can break free by succeeding on a Strength check with a DC equal to the initial Fortitude save. Any land-bound creature two size categories smaller less than the elemental has its speed automatically reduced by half, even if the Strength check is successful. This ability only works on creatures with weight and mass; incorporeal and gaseous creatures are immune to this power. Crush: Once per day per 2HD, as a standard action, a gravity elemental can increase the gravity around itself to crushing proportions. Anything within the gravity elemental's gravity field takes bludgeoning damage. A successful Fortitude save reduces the damage by half. The area of effect and save DC depend on the elemental's size. The save DC is Strength-based."},{"type":"Immunity to Missile Weapons","kind":"Ex","details":"A gravity elemental is immune to any attack from thrown or hurled weapons, arrows, bolts, stones, and similar weapons with a size equal to or less than its own. Any such ranged attack against a gravity elemental automatically fails and the weapon is pulled into the elemental's body. Captured missiles orbit the gravity elemental's form as long as it desires, and it can release one such missile each round as an improvised thrown weapon. The weapon deals its normal damage plus the gravity elemental's Strength modifier, and has a range increment of 20 ft. A gravity elemental has the Throw Anything feat as a bonus feat."},{"type":"Immunity to Spells","kind":"Ex","details":"A gravity elemental is immune to all spells, spell-like abilities, and effects that depend on weight or mass."},{"type":"Perfect Flier","kind":"Ex","details":"A gravity elemental has perfect control over the forces of gravity, and never needs to make a Fly check when attempting a complex maneuver. It must still make Fly checks to resist external influences on its flight, such as strong winds."}],"description":"A gravity elemental embodies the very force that controls and holds together the fabric of the universe. The actual elemental is a tiny, superdense ball of matter deep within a zone of darkness and spiraling arms of debris that comprise the body of the elemental. A gravity elemental has mass and size, but no effective weight. Gravity elementals originate on a weird, recently discovered plane that scholars affectionately call the Plane of Gravity. The elemental's home plane is a flat, rocky place with little life, no known water sources, and no plant life or foliage. The plane is always shrouded in darkness. Dense pockets of intense gravity and areas of little or no gravity dot the barren landscape. Gravity elementals seem to be able to converse with others of their kind by manipulating gravity itself. Gravity elementals attack primarily by flailing at their opponents with multiple arms, each one a mixture of fluctuating fields of micro-gravity and debris that has been sucked into its gravity well. These creatures can also attack by adjusting the local gravity fields around themselves.","ecology":"","habitat_society":""},{"name":"Huge Monstrous Sea Wasp","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"vermin","subtypes":["aquatic"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"watersense","modifier":"60 ft."}],"ac":13,"ac_touch":9,"ac_flat_footed":12,"ac_mods":"+1 Dex, +4 natural, -2 size","hp":52,"hd":"8d8+16","hdvalue":8,"fort":8,"ref":3,"will":2,"defensive_abilities":["transparent"],"immunities":["vermin traits"],"speed":[{"type":"swim","speed":60}],"melee":"tentacle +7 (2d6+4 plus poison)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"entangle"}],"strength":17,"dexterity":13,"constitution":14,"wisdom":10,"charisma":2,"baseatk":6,"cmb":11,"cmd":22,"cmd_special":"can't be tripped","skills":[{"skill":"Escape Artist","value":11},{"skill":"Perception","value":4},{"skill":"Stealth","value":3},{"skill":"Swim","value":11}],"sq":[{"type":"jet"},{"type":"transparent"}],"environments":["warm aquatic"],"organizations":["solitary","ring (2-5)"],"treasure":"incidental","description_visual":"A translucent blue and nearly invisible in water, this cube-shaped jellyfish has four distinct sides and trails dozens of extremely long tentacles.","group":"Sea Wasp","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Entangle","kind":"Ex","details":"A sea wasp can entangle a creature up to two sizes smaller than itself with its tentacles with a successful CMB check. An entangled opponent suffers tentacle damage and the effect of its poison each round the hold is maintained. An entangled creature still receives a save to avoid the effects of its poison. While a foe is entangled, the sea wasp cannot attack any other creature."},{"type":"Poison","kind":"Ex","details":"Sting-injury; the effects of the poison are determined by the creature's size. The DC of the save is Constitution-based. Size Fort DC Frequency Effect Cure Tiny 10 1/round for 1d4 rounds 1 Con 1 save Small 11 1/round for 1d4 rounds 1d2 Con 1 save Medium 11 1/round for 1d6 rounds 1d3 Con 1 save Large 13 1/round for 1d6 rounds 1d4 Con 2 consecutive saves Huge 15 1/round for 1d6 rounds 1d6 Con 2 consecutive saves Gargantuan 20 1/round for 1d6 rounds 1d8 Con 3 consecutive saves"},{"type":"Jet","kind":"Ex","details":"A monstrous sea wasp can jet backward once per round as a full-round action at a speed equal to four times its swim speed. It must move in a straight line, but doesn't provoke attacks of opportunity while jetting."},{"type":"Transparent","kind":"Ex","details":"A monstrous sea wasp is nearly invisible floating in the water. An observer must make a successful DC 20 Perception check to notice the sea wasp."},{"type":"Watersense","kind":"Ex","details":"Monstrous sea wasps can automatically sense the location of anything within 60 ft. that is in contact with water."}],"description":"Monstrous sea wasps are deadly aquatic creatures with long, writhing and highly poisonous tentacles that extend for several yards. They inhabit warm waters and tend to congregate near coastal regions or river mouths where they wait for prey to wash downstream to them. Monstrous sea wasps are also called box jellyfish or marine stingers. Almost invisible in the water, the sea wasp has four eyes, one on each side of the bell, connected to a nerve ring inside the main body. They have no brain, but are able to process visual information. These eyes are invisible to all but the keenest observers. Monstrous sea wasps feed on a variety of marine life including fish, manta rays and stingrays, and crustaceans. The larger monstrous sea wasps also feed on sharks, whales, giant fish, giant squids, octopi, and swimmers. Prey that becomes entangled in its mass of tentacles is quickly stung by the sea wasp and then coiled into its mouth and devoured. Monstrous sea wasps are non-aggressive and don't actively hunt for food. They simply float along in the water waiting for a living creature to swim into its mass of tentacles. When it detects prey in its tentacles, it folds them around the prey, and stings it. A monstrous sea wasp's poison (particularly the larger ones) is meant to instantly kill its prey so it doesn't struggle and damage the sea wasp's delicate form. Sages catalogue the sea wasp's sting as being one of the deadliest and most painful one can experience. A creature stung by a sea wasp that lives to tell about, never forgets its brush with this monstrosity.","ecology":"","habitat_society":""},{"name":"Huge Smoke Elemental","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"outsider","subtypes":["air","elemental","extraplanar","fire"],"init":12,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":22,"ac_touch":17,"ac_flat_footed":13,"ac_mods":"+1 dodge, +8 Dex, +5 natural, -2 size","hp":85,"hd":"10d10+30","hdvalue":10,"fort":10,"ref":15,"will":3,"defensive_abilities":["air mastery","amorphous"],"dr":"5/-","immunities":["elemental traits","fire"],"weaknesses":["vulnerability to cold","vulnerability to wind"],"speed":[{"type":"fly","speed":80,"maneuverability":"perfect"}],"melee":"2 slams +16 (2d6+5 plus burn)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"burn","details":"1d8, DC 18"},{"type":"engulf","details":"DC 20"}],"strength":20,"dexterity":27,"constitution":17,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":10,"cmb":17,"cmd":36,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Escape Artist","value":21},{"skill":"Fly","value":25},{"skill":"Perception","value":13},{"skill":"Stealth","value":13,"special":"+21 in smoke or fog"}],"languages":["Auran"],"sq":[{"type":"gaseous"}],"environments":["any (Plane of Air)","any (Plane of Fire)","any (Plane of Smoke)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"A black cloud of acrid smoke drifts ahead.","group":"Elemental","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Air Mastery","kind":"Ex","details":"Airborne creatures take a -1 penalty on attack and damage rolls against a smoke elemental."},{"type":"Burn","kind":"Ex","details":"A smoke elemental's burn DC includes a -2 racial penalty, as their fires don't burn as hot as a true fire elemental's flames."},{"type":"Engulf","kind":"Ex","details":"A smoke elemental can engulf creatures of its size or smaller into its smoky form as part of a standard action. It cannot make any other attack in which it engulfs. The smoke elemental merely has to move over its opponents, affecting as many as it can cover. Targeted creatures can make attacks of opportunity against the creature, but if they do so, they are not entitled to a saving throw against the engulf attack. Those who don't attempt attacks of opportunity can attempt a Reflex save to avoid being engulfed-on a success, they move back or aside (target's choice). The smoke obscures all sight, including darkvision, beyond 5 ft. and grants concealment to creatures inside the cloud from attacks by opponents that are not adjacent to them. Engulfed opponents don't gain the pinned condition and may move normally. Each round a creature begins its turn engulfed, it suffers from burning eyes (-2 on attack rolls and Perception checks) and takes 3d6 points of fire damage from smoke inhalation. The penalties and damage continue for a number of rounds equal to the smoke elemental's Hit Dice even after escaping the engulf. A creature can make a Fortitude save (DC is listed with each elemental) to end the penalties and damage. The save DCs are Constitution-based."},{"type":"Gaseous","kind":"Ex","details":"A smoke elemental can pass through small holes or narrow openings without reducing its speed."},{"type":"Vulnerability to Wind","kind":"Ex","details":"A smoke elemental is treated as two sizes smaller for purposes of determining the effects high wind has upon it."}],"description":"Smoke elementals are creatures of elemental smoke: part fire, part air. Where the Elemental Plane of Air meets the Elemental Plane of Fire lies a para-elemental plane, that of Elemental Smoke. It is from that black clouded region that these creatures hail.\n\nSmoke elementals spend most of their time on their home plane, only occasionally venturing into the Elemental Planes of Air or Fire. Rarely do they ever enter the Material Plane unless called by a spellcaster.\n\nA smoke elemental appears as a cloud of black smoke or thick fog. No discernible features can be seen in its form, though it can reshape itself at will to form two large eyes and a mouth of empty darkness (which serve no purpose other than to perhaps startle onlookers).","ecology":"","habitat_society":""},{"name":"Hydrodaemon","cr":7,"xp":3200,"alignment":"NE","size":"Large","type":"outsider","subtypes":["aquatic","daemon","evil","extraplanar"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"}],"ac":19,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+2 Dex, +8 natural, -1 size","hp":66,"hd":"7d10+28","hdvalue":7,"fort":9,"ref":7,"will":3,"dr":"10/good","immunities":["acid","death effects","disease","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":18,"speed":[{"type":"land","speed":30},{"type":"fly","speed":40,"maneuverability":"average"},{"type":"swim","speed":60}],"melee":"2 claws +10 (1d6+4), bite +10 (2d6+4 plus grab)","ranged":"sleep spittle +8 (sleep)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rake","details":"2 claws +10, 1d6+4"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"},{"spell":"water walk"}]},{"frequency":"at-will","spells":[{"spell":"cause fear"},{"spell":"create water"},{"spell":"deeper darkness"}]},{"frequency":"1/day","spells":[{"spell":"desecrate"},{"spell":"summon","details":"level 3, hydrodaemon 50%"}]},{"frequency":"2/day","spells":[{"spell":"dimension door"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"}]}],"strength":18,"dexterity":14,"constitution":18,"intelligence":8,"wisdom":11,"charisma":14,"baseatk":7,"cmb":15,"cmb_special":"-6 vs. grapple","cmd":27,"feats":[{"feat":"Cleave"},{"feat":"Point Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"}],"skills":[{"skill":"Fly","value":10},{"skill":"Intimidate","value":12},{"skill":"Knowledge (planes)","value":9},{"skill":"Perception","value":14},{"skill":"Swim","value":22}],"languages":["Common","Daemonic","telepathy 100 ft."],"sq":[{"type":"amphibious"},{"type":"glide"}],"environments":["any (Gehenna)","any (Hades)","any (Tarterus)"],"organizations":["solitary","gang (2-4)","swarm (5-8)","mob (9-14)"],"treasure":"standard","description_visual":"This massive frog-like creature stands nearly 10 ft. tall. Its flesh is warty and dark green and its eyes are sickly yellow. It has large flaps of skin under its arms that seemingly function as wings.","group":"Daemon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Glide","kind":"Ex","details":"A hydrodaemon can launch itself into the air and glide along for 1 minute, gaining a fly speed of 40 ft. and average maneuverability. A gliding hydrodaemon gains the pounce ability."},{"type":"Sleep Spittle","kind":"Ex","details":"A hydrodaemon can fire a line of spittle at a single target within 20 ft., making a ranged touch attack as a standard action. A target hit by the spittle must succeed on a DC 17 Will save or fall asleep for 6 rounds. The save DC is Constitution-based."}],"description":"Hydrodaemons are frog-like daemons that swim the River Styx. They are the only known creatures in existence that can touch the waters of the Styx without suffering any ill effects. Hydrodaemons are 10 ft. tall and weigh about 4,000 pounds. They move by leaping in a manner akin to a frog. Large flaps of skin under their arms allow them seemingly to glide when leaping. The flesh of a hydrodaemon is warty and green. Its eyes are a sickly yellow in color.","ecology":"","habitat_society":"","credit":"The Hydrodaemon originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Juvenile Gray Dragon","cr":7,"xp":3200,"alignment":"NE","size":"Medium","type":"dragon","subtypes":["water"],"init":6,"senses":[{"type":"dragon senses"}],"ac":25,"ac_touch":12,"ac_flat_footed":23,"ac_mods":"+2 Dex, +13 natural","hp":94,"hd":"9d12+36","hdvalue":9,"fort":10,"ref":10,"will":8,"immunities":["paralysis","sleep"],"speed":[{"type":"land","speed":60},{"type":"fly","speed":150,"maneuverability":"average"},{"type":"swim","speed":40}],"melee":"2 claws +14 (1d6+5), bite +15 (1d8+7), 2 wings +14 (1d4+5)","space":"5 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"60-ft. line, 8d6 fire; DC 18 Ref half"}],"spellsknown_caster_level":1,"spellsknown_concentration":5,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"protection from good"},{"spell":"obscuring mist"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ray of frost"},{"spell":"resistance"}]}],"strength":21,"dexterity":14,"constitution":19,"intelligence":13,"wisdom":15,"charisma":13,"baseatk":9,"cmb":14,"cmd":26,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":13},{"skill":"Fly","value":14},{"skill":"Intimidate","value":13},{"skill":"Knowledge (local)","value":13},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":14},{"skill":"Swim","value":25}],"languages":["Common","Draconic Special Abilities"],"environments":["warm coastlines"],"organizations":["solitary"],"treasure":"triple standard","description_visual":"Steam emanates from the nostrils and mouth of this slate gray dragon.","group":"Dragon","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A gray dragon's breath weapon is a superheated line of steam."},{"type":"Change Shape","kind":"Su","details":"A young or older gray dragon can take any animal or humanoid form 3/day as if using polymorph."},{"type":"Corrupt Water","kind":"Sp","details":"Once per day an adult or older gray dragon can stagnate 10 cubic ft. of still water, making it foul and unable to support water-breathing life. The ability spoils liquids containing water. Liquid-based magic items (such as potions) and items in a creature's possession must succeed on a Will save (DC 19) or become ruined. This ability is the equivalent of a 1st-level spell. Its range is 180 ft."},{"type":"Spell-Like Abilities","kind":"Sp","details":"A gray dragon gains the following spell-like abilities, usable at will upon reaching the listed age category. • Young-fog cloud; • Juvenile-create water; • Old-control winds; • Ancient-control water;"},{"type":"Water Breathing","kind":"Ex","details":"A gray dragon breathes water and can use its breath weapon, spells, and abilities underwater."}],"description":"Gray dragons are evil dragons that inhabit mountains and hills near coastlines. They have little regard for other races and often enslave others to do their bidding. Adult and older gray dragons are rarely found without a retinue of humanoid slaves. Gray dragons mate for life and a single mated pair often terrorizes nearby villages, laying waste to those that oppose the dragon's will.","ecology":"","habitat_society":""},{"name":"Kamarupa","cr":7,"xp":3200,"alignment":"CE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["unnatural aura"],"ac":16,"ac_touch":16,"ac_flat_footed":12,"ac_mods":"+2 deflection, +3 Dex, +1 dodge","hp":65,"hd":"10d8","hdvalue":10,"fort":5,"ref":8,"will":12,"defensive_abilities":["+4 channel resistance","incorporeal"],"immunities":["undead traits"],"weaknesses":["Powerless in sunlight"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":80,"maneuverability":"perfect"}],"melee":"incorporeal touch +10 (2d6 plus death touch)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death touch"},{"type":"gaze attack"},{"type":"nightmare"}],"dexterity":16,"intelligence":14,"wisdom":16,"charisma":15,"baseatk":7,"cmb":10,"cmd":26,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":24},{"skill":"Intimidate","value":16},{"skill":"Knowledge (history)","value":12},{"skill":"Knowledge (religion)","value":10},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":11},{"skill":"Stealth","value":16}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This floating nightmare has twisted facial features that are filled with hatred for the living. Their voices sound like the screaming wind, and their forms are insubstantial.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Death Touch","kind":"Su","details":"Creatures hit by a kamarupa's incorporeal touch must make a DC 17 Fort save or die as the touch stops the heart. Even if the save is successful, the creature suffers 2d6 points of damage as the kamarupa clutches its heart. Often, a creature surviving a touch attack acquires a harmless trait or characteristic for 2d4 months. Traits can be a white streak of hair, a nervous twitch, pale complexion or dilated eyes. The save DC is Charisma-based."},{"type":"Frightful Gaze","kind":"Su","details":"A kamarupa's glance creates dread in living beings, at a range of up to 30 ft. Creatures meeting the gaze must make a DC 17 Fortitude save or become panicked for 3d4 rounds. Even if successful, the subject becomes shaken for 1d4 rounds. The save DC is Charisma-based."},{"type":"Nightmare","kind":"Su","details":"Once per night, a kamarupa places a nightmare on one creature it has encountered. They prefer to send the nightmare to particularly powerful opponents or priests night after night until the opponent dies. The target can resist the attack with a DC 17 Will save. A creature that drops any possession (while panicked) near the kamarupa suffers a -4 penalty to the save until the item is recovered. A creature that successfully saves is immune to the nightmare for 24 hours. The save DC is Charisma-based."},{"type":"Powerless in Sunlight","kind":"Ex","details":"Kamarupas are powerless in natural sunlight (not merely a daylight spell) and flee before it. A kamarupa caught in sunlight cannot attack and can take only a single move action each round. Kamarupas lose one-third of their hit points each round spent in direct sunlight."},{"type":"Unnatural Aura","kind":"Su","details":"Animals sense the kamarupa's unnatural presence at 30 ft. They panic if forced to get closer and remain panicked while within range."}],"description":"A kamarupa appears as a mockery of its former fleshbound life. Its hollow eyes and mouth are black voids, and its facial features twist and stretch into a nightmarish appearance. Kamarupa are the distorted souls of evil priests betrayed and sacrificed to their deity.\n\nKamarupas are highly intelligent and communicate in voices similar to the screaming wind. They hate life and light. A kamarupa is roughly human-sized and weightless. A kamarupa attacks with its heart-stopping touch. It uses its incorporeal nature to move through walls, ceilings and floors to attack.","ecology":"","habitat_society":"","credit":"Original author Gary Schotter & Jeff Harkness  Originally appearing in Splinters of Faith Adventure 5: Eclipse of the Hearth (© Frog God Games/ Gary Schotter & Jeff Harkness, 2010)"},{"name":"Lead Skeleton","cr":7,"xp":3200,"alignment":"N","size":"Medium","type":"construct","init":4,"senses":[{"type":"blindsight","modifier":"90 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":24,"ac_touch":14,"ac_flat_footed":20,"ac_mods":"+4 Dex, +10 natural","hp":75,"hd":"10d10+20","hdvalue":10,"fort":3,"ref":7,"will":3,"dr":"10/adamantine and bludgeoning","immunities":["acid","cold","electricity","fire","magic","construct traits"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +16 (1d8+6)","space":"5 ft.","reach":"5 ft.","strength":22,"dexterity":18,"wisdom":10,"charisma":1,"baseatk":10,"cmb":16,"cmd":30,"environments":["any"],"organizations":["solitary","group (2-6)"],"treasure":"no coins, double goods (gems only), no items","description_visual":"This creature appears to be an animated skeleton whose bones have been coated with metal.","group":"Skeleton","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Immunity to Magic","kind":"Ex","details":"A lead skeleton is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted below. A magical attack that deals sonic damage slows a lead skeleton (as the slow spell) for 1d4 rounds, with no saving throw."}],"description":"Lead skeletons appear simply to be skeletons coated with metal. Despite their outward appearance, they are actually golem-like constructs and not undead. Therefore, they cannot be turned.\n\nLead skeletons appear as 6-foot tall skeletons constructed of metal.\n\nSome have gemstones encrusted in the body and eye sockets. A lead skeleton is expensive to create. Those who choose to create such creatures prefer the added fear and awe the skeletons tend to receive, and have a great deal of additional wealth and time.\n\nLead skeletons can be programmed to attack only certain creatures or be programmed to accept certain passwords or types of clothing. More complex programming tends to fail. While lead skeletons might not have the same abilities as other golems, their immunities and speed make them extraordinarily dangerous. They use their fists to inflict large amounts of damage and attack a single target until it is dead.\n\nConstruction Bones from a full humanoid skeleton are carefully sheathed in an alloy of lead and iron and rejoined with iron or steel hinges. The total cost of the body must be at least 2,000 gp. An elemental spirit is summoned during the creation and bound to the body. To bind the elemental spirit, the creator must summon and confine an elemental using any of the planar binding spells.\n\nLEAD SKELETON CL 14th; Price 41,000 gp Requirements Craft Construct, geas/quest, limited wish, polymorph any object, resist energy (fire, cold, electricity, acid), planar binding (any), caster must be at least 14th level; Skill Craft (armor) DC 16 or Craft (weapons) DC 16; Cost 21,500 gp","ecology":"","habitat_society":""},{"name":"Lurker Above","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"aberration","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":19,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+1 Dex, +10 natural, -2 size","hp":95,"hd":"10d8+40","hdvalue":10,"fort":7,"ref":4,"will":9,"defensive_abilities":["amorphous"],"dr":"10/slashing or piercing","resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":10},{"type":"climb","speed":5},{"type":"fly","speed":40,"maneuverability":"poor"}],"melee":"slam +15 (3d8+15 plus grab)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"3d6+15"},{"type":"smother"}],"strength":30,"dexterity":12,"constitution":19,"intelligence":2,"wisdom":15,"charisma":9,"baseatk":7,"cmb":19,"cmb_special":"+4 vs. grapple","cmd":31,"cmd_special":"can't be tripped","feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Climb","value":23},{"skill":"Fly","value":1},{"skill":"Perception","value":12},{"skill":"Stealth","value":8,"special":"+16 in rocky areas"}],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard","description_visual":"A black manta ray-like creature three times the size of a normal human flies toward you. Its body is black changing to gray on its inside or underbelly.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Smother","kind":"Ex","details":"When a lurker above grapples a target, it forms an airtight seal around its prey. A grappled target cannot speak or cast spells with verbal components and must hold its breath (see the Suffocation)."}],"description":"The lurker above is a subterranean carnivore that preys on any living creatures that enter its territory. These creatures are extremely territorial and are never encountered with others of their kind. Mating habits among lurkers is unknown to sages as no two of these creatures have ever been encountered together. A typical lurker above has a hunting territory of several square miles. A lurker above waits for its prey, clinging to the ceiling, roof, or other such overhang. When prey passes beneath it, the lurker above drops from its hiding place and wraps itself around its prey. Lurker Below The lurker below is an aquatic variety of lurker above that makes its lair in any body of water and in any climate (though it rarely lairs in extremely cold climates). Lurkers below are pale blue or black in color and are often mistaken for giant manta rays. Lurkers below cannot fly, but have a swim speed of 40 ft. They are otherwise identical to their landbased counterparts detailed above.","ecology":"","habitat_society":"","credit":"The Lurker Above originally appeared in the Strategic Review #3 (© TSR/Wizards of the Coast, 1975) and later in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission."},{"name":"Magma Ooze","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"ooze","subtypes":["fire"],"init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":4,"ac_touch":4,"ac_flat_footed":4,"ac_mods":"-5 Dex, -1 size, +0 natural","hp":120,"hd":"10d8+60","hdvalue":10,"fort":9,"ref":-2,"will":-2,"defensive_abilities":["split (piercing and slashing, 10 hp)"],"immunities":["fire","ooze traits"],"speed":[{"type":"land","speed":10},{"type":"climb","speed":10}],"melee":"slam +9 (2d4+4 plus 2d6 fire and grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"2d4+4 plus 2d6 fire"},{"type":"lava"}],"strength":16,"dexterity":1,"constitution":23,"wisdom":1,"charisma":1,"baseatk":7,"cmb":11,"cmb_special":"+4 vs. grapple","cmd":16,"cmd_special":"can't be tripped","skills":[{"skill":"Climb","value":11}],"environments":["any underground","warm mountains"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature appears to be a pool of bubbling and churning molten rock.","group":"Ooze","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Lava","kind":"Ex","details":"The magma ooze is formed of molten rock. Any melee hit deals on the ooze inflicts 2d6 points of fire damage to the attacker. The damage continues for 1d3 rounds, but deals only 1d6 damage during this time."}],"description":"A magma ooze is encountered primarily on the Material Plane but is thought to have its origins on the Plane of Fire. They are almost always found in or near volcanoes and other warm or hot places. Magma oozes don't approach water and are never found near such sources. Magma oozes can grow to a length of 10 ft., with a thickness of about 6 inches.","ecology":"","habitat_society":""}];
